// ELEMENTS:
// 1. Fundo navy liso
// 2. Foto opcional (src) no terço de cima, a fundir-se no azul por gradiente
// 3. Rótulo "PREÇO" (label) em ink
// 4. Preço em serifa branca grande (anim.text), com o tracking a fechar devagar
// 5. Barra coral + linha de apoio opcional (sub) em ink
// 6. Grão de filme + vinheta
import React, { useId } from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#161617";
const CYAN = "#FFFFFF";
const CORAL = "#FFFFFF";
const INK = "#161617";
const WHITE = "#FFFFFF";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 45%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.22) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const PrecoRevelacao: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const land = format === "landscape";
  const u = land ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const T = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const src = String(p.src ?? "");
  const price = String(anim.text ?? p.price ?? "").trim();
  const label = String(p.label ?? "Preço").trim();
  const sub = String(p.sub ?? "").trim();

  const show = (delay: number, len = 0.7): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing: EASE });
  const rise = (delay: number): React.CSSProperties => {
    const t = show(delay);
    return { opacity: t, transform: `translateY(${(1 - t) * 20 * u}px)` };
  };
  const photoH = src ? (land ? H : H * 0.44) : 0;
  const scale = interpolate(f, [0, T], [1.02, 1.08], clamp);
  const tPrice = show(0.35, 1.1);
  const priceSize = Math.min(184 * u, ((land ? W * 0.5 : W) - 144 * u) / Math.max(4, price.length * 0.5));

  return (
    <AbsoluteFill style={{ textShadow: "0 2px 18px rgba(0,0,0,0.45)", overflow: "hidden", backgroundColor: NAVY }}>
      {src ? (
        <div style={{ position: "absolute", left: 0, top: 0, width: land ? W * 0.45 : W, height: photoH, overflow: "hidden", opacity: show(0, 0.5) }}>
          <Img src={src} style={{ width: "100%", height: "100%", objectFit: "cover", filter: "saturate(0.88) contrast(1.05)", transform: `scale(${scale})` }} />
          <AbsoluteFill
            style={{ background: land ? `linear-gradient(90deg, rgba(22,22,23,0) 60%, ${NAVY} 100%)` : `linear-gradient(180deg, rgba(22,22,23,0) 62%, ${NAVY} 100%)` }}
          />
        </div>
      ) : null}
      <div
        style={{
          position: "absolute",
          left: land ? W * 0.45 : 0,
          right: 0,
          top: land ? 0 : photoH,
          bottom: 0,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          gap: 40 * u,
          textAlign: "center",
          paddingBottom: land ? 0 : 120 * u,
        }}
      >
        <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 38 * u, letterSpacing: "0.22em", textTransform: "uppercase", color: WHITE, ...rise(0.2) }}>
          {label}
        </div>
        <div
          style={{
            fontFamily: FONTS.display,
            fontVariantNumeric: "lining-nums",
            fontWeight: 300,
            fontSize: priceSize,
            lineHeight: 1,
            color: WHITE,
            whiteSpace: "nowrap",
            opacity: tPrice,
            letterSpacing: `${(1 - tPrice) * 0.12}em`,
          }}
        >
          {price}
        </div>
        <div style={{ width: interpolate(tPrice, [0.4, 1], [0, 96 * u], clamp), height: 4 * u, background: CORAL }} />
        {sub ? (
          <div style={{ fontFamily: FONTS.body, fontWeight: 600, fontSize: 36 * u, letterSpacing: "0.2em", textTransform: "uppercase", color: WHITE, ...rise(1.0) }}>{sub}</div>
        ) : null}
      </div>
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default PrecoRevelacao;
